const fs = require('fs');
const crypto = require('crypto');

function deepMerge(a, b) {
  if (!b) return a;
  const out = { ...a };
  for (const k of Object.keys(b)) {
    if (
      b[k] &&
      typeof b[k] === 'object' &&
      !Array.isArray(b[k]) &&
      a[k] &&
      typeof a[k] === 'object' &&
      !Array.isArray(a[k])
    ) {
      out[k] = deepMerge(a[k], b[k]);
    } else {
      out[k] = b[k];
    }
  }
  return out;
}

function loadGlobalVarsOptional() {
  try {
    const envJson = String($env.CASTUO_GLOBAL_VARS_JSON || '').trim();
    if (envJson) {
      let base = JSON.parse(envJson);
      const ov = String($env.CASTUO_GLOBAL_VARS_OVERRIDE_PATH || '').trim();
      if (ov && fs.existsSync(ov)) base = deepMerge(base, JSON.parse(fs.readFileSync(ov, 'utf8')));
      return base;
    }
    const p = String($env.CASTUO_GLOBAL_VARS_PATH || '').trim();
    if (p && fs.existsSync(p)) {
      let base = JSON.parse(fs.readFileSync(p, 'utf8'));
      const ov = String($env.CASTUO_GLOBAL_VARS_OVERRIDE_PATH || '').trim();
      if (ov && fs.existsSync(ov)) base = deepMerge(base, JSON.parse(fs.readFileSync(ov, 'utf8')));
      return base;
    }
  } catch (e) {
    return null;
  }
  return null;
}

const item = $input.first().json;
const body = item.body && typeof item.body === 'object' ? item.body : item;
const cfg = loadGlobalVarsOptional();
const db = (cfg && cfg.database) || {};
const notify = (cfg && cfg.notifications && cfg.notifications.slack) || {};
const ext = (cfg && cfg.external_services) || {};

const table =
  String($env.N8N_DB_COSECHAS || '').trim() || db.cosechas || 'castuo_prod_cosechas';

const gaiaUrl =
  String($env.N8N_GAIACHAIN_API || '').trim() || String(ext.gaiachain?.api_endpoint || '').trim();
const gaiaKey =
  String($env.N8N_GAIACHAIN_API_KEY || '').trim() || String(ext.gaiachain?.api_key || '').trim();

const slackChannel =
  String($env.N8N_SLACK_ALERTS || '').trim() || notify.slack_channel || '#alertas-castuo';

const now = new Date();
const fecha = body.fecha_cosecha || now.toISOString().split('T')[0];
const row = {
  cultivo_id: String(body.cultivo_id || ''),
  fecha_cosecha: fecha,
  peso_total: Number(body.peso_total || 0),
  calidad: String(body.calidad || 'A'),
};
if (!row.cultivo_id) throw new Error('cultivo_id requerido');
const canon = JSON.stringify(row);
const hash_trazabilidad = crypto.createHash('sha256').update(canon).digest('hex');

let gaia = {
  skipped: true,
  reason:
    'Sin N8N_GAIACHAIN_API + clave (preferir Credencial Header Auth en n8n; no versionar API keys en .env en prod).',
};
if (gaiaUrl && gaiaKey) {
  try {
    const base = gaiaUrl.replace(/\/$/, '');
    const validatePath = String($env.N8N_GAIACHAIN_VALIDATE_PATH || '/validate').trim();
    const suffix = validatePath.startsWith('/') ? validatePath : '/' + validatePath;
    const r = await fetch(base + suffix, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: 'Bearer ' + gaiaKey,
      },
      body: JSON.stringify({ hash: hash_trazabilidad, data: row }),
    });
    gaia = { http_status: r.status, text: await r.text() };
  } catch (e) {
    gaia = { error: e.message };
  }
}

const audit = {
  timestamp: now.toISOString(),
  operacion: 'Guardar Cosecha',
  tabla_destino: table,
  datos: { cultivo_id: row.cultivo_id, hash_trazabilidad },
  usuario_workflow: 'CASTUO_Guardar_Cosechas',
};

return [
  {
    json: {
      config_source: cfg ? 'global_vars_optional' : 'env_defaults',
      castuo_global: cfg,
      row: { ...row, hash_trazabilidad },
      data_table: {
        table,
        note: 'Data Table / Postgres: insert con cultivo_id, fecha_cosecha, peso_total, calidad, hash_trazabilidad.',
      },
      gaia,
      audit,
      slack_preview: {
        channel: slackChannel,
        text: 'Nueva cosecha ' + row.cultivo_id + ' hash ' + hash_trazabilidad,
      },
    },
  },
];
